  'msg.SHARE_OVERRUN': ['{khatian}-এ {seller}-এর অংশ {share} ({held} শতাংশ), কিন্তু এই দলিলে {sold} শতাংশ বিক্রি দেখানো হয়েছে।', '{seller} holds {share} ({held} dec) in {khatian} but this deed sells {sold} dec.'],
  'msg.OVERLAPPING_SALE': ['{seller} এই জমির {prior} শতাংশ আগেই বিক্রি করেছেন ({deeds})। এই দলিল ধরলে মোট দাঁড়ায় {total} শতাংশ, অথচ রেকর্ডে আছে {held} শতাংশ।{note}', '{seller} already sold {prior} dec of this parcel ({deeds}); with this deed the total is {total} dec, above the {held} dec on record.{note}'],
  'msg.OVERLAPPING_SALE.rej': ['{deeds} দলিলের নামজারি প্রত্যাখ্যাত হয়েছিল, কিন্তু প্রত্যাখ্যাত নামজারি নিবন্ধিত দলিল বাতিল করে না।', 'The mutation of {deeds} was rejected, but a rejected mutation does not cancel a registered deed.'],
  'msg.SELLER_NOT_RECORDED_OWNER.pending': ['{seller} এখনো সর্বশেষ খতিয়ান {khatian}-এ নেই, কিন্তু {via} দলিলে তিনি এই জমি কিনেছেন এবং সেই নামজারি এখনো চলমান। নিবন্ধনের আগে ওই দলিল ও নামজারি দেখে নিন।', '{seller} is not yet in the latest khatian {khatian}, but bought this parcel in {via} and that mutation is still open. Check that deed and its mutation before registering.'],
  'msg.DATA_NOT_VERIFIABLE': ['দলিল {deed} পুরোপুরি যাচাই করা যায়নি: {what}। একে “যাচাই হয়নি” ধরুন।', 'Deed {deed} could not be fully verified: {what}. Treat it as not checked.'],
  'msg.dnv.plot': ['দাগটি রেকর্ডে পাওয়া যায়নি', 'its plot is not in the record'],
  'msg.dnv.area': ['বিক্রির পরিমাণ শূন্যের বেশি সংখ্যা নয়', 'the area sold is not a positive number'],
  'msg.dnv.date': ['নিবন্ধনের তারিখ নেই বা ভুল', 'the registration date is missing or invalid'],
  'msg.dnv.future': ['নিবন্ধনের তারিখ যাচাইয়ের তারিখের পরে', 'the registration date is after the check date'],
  'msg.dnv.dup': ['এই দলিল নম্বর আরেকটি দলিলে আগেই আছে', 'another deed already uses this deed number'],
  'msg.MUTATION_AREA_MISMATCH': ['নামজারি কেস {mutation}-এ {mutated} শতাংশ বদল হয়েছে, কিন্তু দলিলে হস্তান্তর {sold} শতাংশ।', 'Mutation {mutation} changed {mutated} dec but the deed transfers {sold} dec.'],
  'msg.REGISTERED_NOT_MUTATED': ['নিবন্ধনের পর {days} দিন পেরিয়েছে, কিন্তু কোনো নামজারি কেস নেই। রেকর্ডে এখনও আগের মালিকের নাম।', 'Registered {days} days ago with no mutation case; the record of rights still shows the old owner.'],
  'msg.REJECTED_THEN_RESUBMITTED': ['নামজারি প্রত্যাখ্যাত হয়েছিল (কারণ: {reason}) এবং আবার দাখিল করা হয়েছে।', 'Mutation was rejected ({reason}) and has been resubmitted.'],
  'reason.dcr': ['দাগের তফসিল বা ডিসিআর (ভূমি উন্নয়ন কর রশিদ) নেই', 'missing dag schedule / DCR'],

  // ── citizen sentences (no details about other people’s deeds) ──
  'cit.OVERLAPPING_SALE': ['এই জমির কিছু অংশ আগেই বিক্রি হিসেবে নথিভুক্ত আছে। একই জমি দ্বিতীয়বার বিক্রির ঝুঁকি আছে।', 'Part of this land is already on file as sold. There is a risk it is being sold a second time.'],
  'cit.SHARE_OVERRUN': ['বিক্রেতা রেকর্ডে যতটুকু অংশের মালিক, তার চেয়ে বেশি জমি বিক্রি করছেন।', 'The seller is selling more than the share the record shows for them.'],
  'cit.KHAS_CONFLICT': ['রেকর্ড অনুযায়ী এটি সরকারি (খাস) জমি। টাকা দেওয়ার আগে ভূমি অফিসে নিশ্চিত হোন।', 'The record shows this as government (khas) land. Confirm with the land office before paying anything.'],
  'cit.SELLER_NOT_RECORDED_OWNER': ['বিক্রেতার নাম সর্বশেষ রেকর্ডে মালিক হিসেবে নেই।', 'The seller’s name is not in the latest record as an owner.'],
  'cit.INVALID_QR_OR_SIGNATURE': ['দলিলের QR কোড বা স্বাক্ষর মেলেনি। দলিলটি পরিবর্তিত বা জাল হতে পারে।', 'The deed’s QR code or signature did not check out. It may be altered or forged.'],
  'cit.DATA_NOT_VERIFIABLE': ['আপনার দেওয়া তথ্য রেকর্ডের সঙ্গে মেলানো যায়নি, তাই যাচাই সম্পূর্ণ হয়নি। এটি “ঠিক আছে” নয়; ভূমি অফিসে নিশ্চিত হোন।', 'We could not match what you entered to the record, so the check is incomplete. This is not a “clear”; confirm with the land office.'],
  'cit.SELLER_PENDING': ['বিক্রেতার নাম সর্বশেষ রেকর্ডে এখনো নেই। আগের কোনো বিক্রির পর রেকর্ড হালনাগাদ হওয়ার সময় এমন হতে পারে। টাকা দেওয়ার আগে ভূমি অফিসে নিশ্চিত হোন।', 'The seller’s name is not in the latest record yet. This can happen while the record is catching up with an earlier sale. Get this confirmed at the land office before you pay.'],
  'cit.mutation': ['এই জমির নামজারি নিয়ে অমীমাংসিত বিষয় আছে।', 'There is an open question about this land’s mutation.'],

