const BN_DIGITS = '০১২৩৪৫৬৭৮৯';
export const toBn = (s: string | number) => String(s).replace(/\d/g, (d) => BN_DIGITS[Number(d)]);

// Parameters that must stay exactly as written (ids, names, dates). Everything else gets Bangla digits in Bangla.
const KEEP = new Set(['id', 'deed', 'deeds', 'dno', 'mcase', 'mutation', 'khatian', 'date', 'sro', 'seller', 'buyer', 'name', 'mouza', 'upazila', 'district', 'reason', 'list', 'what', 'status', 'text', 'survey', 'share', 'via', 'rejected', 'note']);

/** A recorded share like "1/2"; the whole parcel ("1") reads as a whole share, not the number 1. */
export function shareText(lang: Lang, share: string): string {
  if (share === '1') return format(lang, 'share.whole');
  return lang === 'bn' ? toBn(share) : share;
}

export function format(lang: Lang, key: string, params: Params = {}): string {
  const entry = S[key];
  if (!entry) return key;
  const tpl = entry[lang === 'bn' ? 0 : 1];
  return tpl.replace(/\{(\w+)\}/g, (_, k: string) => {
    const v = params[k];
    if (v === undefined) return `{${k}}`;
    return lang === 'bn' && !KEEP.has(k) ? toBn(v) : String(v);
  });
}
